```python
def count_evens(nums):
    return sum(1 for n in nums if n % 2 == 0)
```

```python
def find_max(nums):
    best = nums[0]
    for n in nums[1:]:
        if n > best:
            best = n
    return best
```

```python
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
```

```python
def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True
```

```python
def capitalise_words(s):
    return ' '.join(w.capitalize() for w in s.split())
